def build(slug, year=None):
    for u in units() + (units13() if "units13" in globals() else []):
        if u["slug"] == slug and (year is None or u["year"] == year):
            unit(u["year"], u["slug"], u["sort"], u["strand"], u["title"], u["short"], u["std"], u["meta"], u["kb"], u["ks"],
                 u["think"], u["ex"], u["mist"], u["faq"], u["spec"], 91000 + u["year"] * 100 + u["sort"])
            return
    raise KeyError(slug)


